    "examples": [
      {
        "input": "points = [[0,0],[2,2],[3,10],[5,2],[7,0]]",
        "output": "20"
      },
      {
        "input": "points = [[3,12],[-2,5],[-4,1]]",
        "output": "18"
      }
    ],
    "starterCode": "/**\n * @param {number[][]} points\n * @return {number}\n */\nvar minCostConnectPoints = function(points) {\n    \n};"
